SELECT (percentile_cont(0.75) within GROUP (ORDER BY los) - percentile_cont(0.25) within GROUP (ORDER BY los)) AS interquartile_range FROM (SELECT icustays.los FROM icustays JOIN patients ON icustays.subject_id = patients.subject_id JOIN admissions ON icustays.subject_id = admissions.subject_id JOIN diagnoses_icd ON admissions.subject_id = diagnoses_icd.subject_id WHERE patients.gender = 2 AND patients.anchor_year = 2019 AND patients.anchor_year_group = 76 AND diagnoses_icd.icd_code = 'I64.9' AND icustays.los IS NOT NULL) UNION ALL (SELECT icustays.los FROM icustays JOIN patients ON icustays.subject_id = patients.subject_id JOIN admissions ON icustays.subject_id = admissions.subject_id JOIN diagnoses_icd ON admissions.subject_id = diagnoses_icd.subject_id WHERE patients.gender = 2 AND patients.anchor_year = 2019 AND patients.anchor_year_group BETWEEN 71 AND 81 AND diagnoses_icd.icd_code = 'I64.9' AND icustays.los IS NOT NULL);